package com.mantou.salesdialer.contacts;
import android.app.*;import android.os.Bundle;import android.text.InputType;import android.widget.*;
/** No JS bridge or intent-supplied configuration. Pairing is a native local operator action. */
public final class EnterpriseConnectionActivity extends Activity {
 private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();private TextView status;private EditText code;private Button pair,usb;private boolean busy;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(32,40,32,32);setContentView(body);TextView title=new TextView(this);title.setTextSize(22);title.setText("电脑连接设置");body.addView(title);status=new TextView(this);status.setText(EnterpriseConnection.label(this)+"\n电脑保持开机，手机与电脑连接同一Wi-Fi。配对码只从自己的电脑获取，不向他人发送。更换连接会暂停本机队列并退出账号。");body.addView(status);code=new EditText(this);code.setHint("粘贴电脑提供的配对码");code.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);code.setSaveEnabled(false);body.addView(code);pair=new Button(this);pair.setText("配对Wi-Fi企业服务");body.addView(pair);pair.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("确认连接自己的电脑").setMessage("将使用配对码中的加密连接；旧队列停止并重新登录。不会启动任何通话。").setNegativeButton("取消",null).setPositiveButton("确认配对",(d,w)->apply(false)).show());usb=new Button(this);usb.setText("恢复USB连接");body.addView(usb);usb.setOnClickListener(v->apply(true));}
 private void apply(boolean reset){if(busy)return;busy=true;pair.setEnabled(false);usb.setEnabled(false);final String raw=code.getText().toString().trim();code.setText("");worker.execute(()->{String message;try{if(!PilotPhoneRuntime.idle(this))throw new IllegalStateException("DEVICE_BUSY");if(reset)EnterpriseConnection.usb(this);else EnterpriseConnection.pair(this,raw);message=EnterpriseConnection.label(this)+"\n已保存，请返回企业工作区重新登录。尚未授权或启动通话。";}catch(Exception e){message="设置未完成，请检查配对码和手机空闲状态；没有启动通话。";}final String result=message;runOnUiThread(()->{status.setText(result);busy=false;pair.setEnabled(true);usb.setEnabled(true);});});}
 @Override protected void onDestroy(){worker.shutdown();super.onDestroy();}
}
